with j as (select * from jsonb_to_recordset($law7d0052$[{"code_id":"NK_RF","article_number":"105.7","version_date":"2000-07-31","article_text":"1) метод сопоставимых рыночных цен;\n\n2) метод цены последующей реализации;\n\n3) затратный метод;\n\n4) метод сопоставимой рентабельности;\n\n5) метод распределения прибыли.\n\nМетод сопоставимых рыночных цен используется для определения соответствия цены, примененной в контролируемой сделке, рыночной цене в порядке, установленном статьей 1059 настоящего Кодекса, при наличии на соответствующем рынке товаров (работ, услуг) хотя бы одной сопоставимой сделки, предметом которой являются идентичные (при их отсутствии - однородные) товары (работы, услуги), а также при наличии достаточной информации о такой сделке.\n\nПри этом для применения метода сопоставимых рыночных цен в целях определения соответствия цены, примененной налогоплательщиком в контролируемой сделке, в качестве сопоставляемой сделки возможно использование сделки, совершенной указанным налогоплательщиком с лицами, не являющимися взаимозависимыми с указанным налогоплательщиком, при условии, что такая сделка является сопоставимой с анализируемой сделкой.\n\nЕсли иное не предусмотрено настоящей главой, используется тот метод, который с учетом фактических обстоятельств и условий контролируемой сделки позволяет наиболее обоснованно сделать вывод о соответствии или несоответствии цены, примененной в сделке, рыночным ценам.\n\nОднородными сделками для целей главы 142 настоящего Кодекса, настоящей главы и глав 144 - 146 настоящего Кодекса признаются сделки, предметом которых могут являться идентичные (однородные) товары (работы, услуги) и которые совершены в сопоставимых коммерческих и (или) финансовых условиях.\n\nПри невозможности обеспечения сопоставимости данных бухгалтерской (финансовой) отчетности для целей расчета интервала рентабельности и определения для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица, используются методы, указанные в подпунктах 4 и 5 пункта 1 настоящей статьи. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nПри этом под разовой сделкой в целях настоящей статьи понимается сделка, экономическая суть которой отличается от основной деятельности организации и которая осуществляется на разовой основе.\n\n10. Методы, указанные в подпунктах 4 и 5 пункта 1 настоящей статьи, могут применяться без непосредственного расчета значений рыночных цен. При использовании указанных методов федеральный орган исполнительной власти, уполномоченный по контролю и надзору в области налогов и сборов, сопоставляет финансовые показатели (результаты) анализируемой сделки (группы однородных анализируемых сделок) с интервалом рентабельности (рассчитанными на основе интервала рентабельности финансовыми показателями) по сопоставимым сделкам, на основании чего производит расчет суммы доходов (прибыли, выручки), которая была бы получена в случае, если бы сторонами данной сделки являлись лица, не признаваемые взаимозависимыми.\n\n11. Судом могут быть учтены иные обстоятельства, имеющие значение для определения соответствия цены, примененной в сделке, рыночной цене, без ограничений, предусмотренных главой 142 настоящего Кодекса и настоящей главой.\n\n12. Налогоплательщики при заключении сделок не обязаны руководствоваться методами, указанными в пункте 1 настоящей статьи, для обоснования своей политики в области ценообразования в целях, не предусмотренных настоящим Кодексом.","article_title":"Статья 105.7. Общие положения о методах, используемых при определении для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1f28e12e07e7ebbbdc64b373d4bfaef538c5c848aaccb9d332e086db02915720"},{"code_id":"NK_RF","article_number":"105.8","version_date":"2000-07-31","article_text":"1. При определении для целей налогообложения доходов (прибыли, выручки) в сделках, сторонами которых являются взаимозависимые лица, могут быть использованы в порядке, предусмотренном статьями 10510 - 10513 настоящего Кодекса, следующие показатели рентабельности:\n\n1) валовая рентабельность, определяемая как отношение валовой прибыли к выручке от продаж, исчисленной без учета акцизов и налога на добавленную стоимость;\n\n2) валовая рентабельность затрат, определяемая как отношение валовой прибыли к себестоимости проданных товаров (работ, услуг);\n\n3) рентабельность продаж, определяемая как отношение прибыли от продаж к выручке от продаж, исчисленной без учета акцизов и налога на добавленную стоимость;\n\n4) рентабельность затрат, определяемая как отношение прибыли от продаж к сумме себестоимости проданных товаров (работ, услуг), коммерческих и управленческих расходов, связанных с продажей товаров (работ, услуг);\n\n5) рентабельность коммерческих и управленческих расходов, определяемая как отношение валовой прибыли к коммерческим и управленческим расходам, связанным с продажей товаров (работ, услуг);\n\n6) рентабельность активов, определяемая как отношение прибыли от продаж к текущей рыночной стоимости активов (внеоборотных и оборотных), прямо или косвенно используемых в анализируемой сделке. В отсутствие необходимой информации о текущей рыночной стоимости активов рентабельность активов может определяться на основании данных бухгалтерской (финансовой) отчетности. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n2. Показатели, указанные в пункте 1 настоящей статьи, и иные\n\nфинансовые показатели для целей настоящей главы определяются для российских организаций на основании данных бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством Российской Федерации о бухгалтерском учете. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nУказанные финансовые показатели для иностранных организаций определяются на основании данных бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством иностранных государств. При этом для целей обеспечения сопоставимости с данными бухгалтерской (финансовой) отчетности, которая составляется в соответствии с законодательством Российской Федерации о бухгалтерском учете, проводится корректировка таких данных. (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\nВыбор указанных организаций осуществляется с учетом их отраслевой специфики и соответствующих видов деятельности, осуществляемых ими в сопоставимых экономических (коммерческих) условиях относительно анализируемой сделки.\n\nПри отсутствии в отрасли, к которой принадлежит лицо, являющееся стороной анализируемой сделки, организаций, не являющихся взаимозависимыми с указанным лицом, выбор организаций для проведения анализа осуществляется с учетом сопоставимости функций, осуществляемых этими организациями, принимаемых ими рисков и используемых активов.\n\nВ отсутствие информации о четырех и более сопоставимых сделках либо в отсутствие информации о бухгалтерской (финансовой) отчетности четырех и более сопоставимых организаций в целях определения интервала рентабельности может использоваться информация о меньшем количестве сопоставимых сделок (бухгалтерской (финансовой) отчетности меньшего количества организаций). (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n1) совокупность значений рентабельности, которые используются для определения интервала рентабельности, упорядочивается по возрастанию, образуя выборку, используемую для определения этого интервала. При этом каждому значению рентабельности, начиная с минимального, присваивается порядковый номер. В случае, если выборка содержит два и более одинаковых значения рентабельности, в выборку включаются все такие значения. При определении интервала рентабельности не учитывается рентабельность анализируемой сделки;\n\n2) минимальное значение интервала рентабельности определяется в следующем порядке:\n\nесли частное от деления на четыре числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то минимальным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на четыре числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то минимальным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n3) максимальное значение интервала рентабельности определяется в следующем порядке:\n\nесли произведение 0,75 и числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то максимальным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли произведение 0,75 и числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то максимальным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n4) медианное значение интервала рентабельности определяется в следующем порядке:\n\nесли частное от деления на два числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то медианным значением интервала рентабельности признается среднее арифметическое значения рентабельности, имеющего в выборке порядковый номер, равный этому целому числу, и значения рентабельности, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на два числа значений рентабельности в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то медианным значением интервала рентабельности признается значение рентабельности, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу.\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) если организация осуществляет сопоставимую деятельность и выполняет сопоставимые функции, связанные с этой деятельностью. Сопоставимость деятельности может определяться с учетом видов экономической деятельности, предусмотренных Общероссийским классификатором видов экономической деятельности, а также международными и иными классификаторами;\n\n2) если совокупная величина чистых активов организации не является отрицательной по данным бухгалтерской (финансовой) отчетности по состоянию на 31 декабря последнего года из нескольких лет, за которые рассчитывается рентабельность; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n3) если организация не имеет убытков от продаж по данным бухгалтерской (финансовой) отчетности более чем в одном году из нескольких лет, за которые рассчитывается рентабельность; (В редакции Федерального закона от 29.06.2012 № 97-ФЗ)\n\n4) если организация не участвует прямо и (или) косвенно в другой организации с долей такого участия более 25 процентов (за исключением случаев, когда доступны сведения о консолидированной финансовой отчетности организаций, которые используются для расчета интервала рентабельности) или не имеет в качестве участника (акционера) организацию с долей прямого участия более 25 процентов.\n\nК указанной выше информации относится информация налогоплательщика о совершенных им сделках с лицами, не являющимися с ним взаимозависимыми.","article_title":"Статья 105.8. Финансовые показатели и интервал рентабельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6cfa1fa6d8ff33bce2eefa568b4dfe6aa9115bef36009ee14da27b43a88579b"},{"code_id":"NK_RF","article_number":"105.9","version_date":"2000-07-31","article_text":"1) совокупность цен, примененных в сопоставимых сделках, которые используются для определения интервала рыночных цен, упорядочивается по возрастанию, образуя выборку, используемую для определения этого интервала. При этом каждому значению цены, начиная с минимального, присваивается порядковый номер. В случае, если выборка содержит два и более одинаковых значения цены, в выборку включаются все такие значения. При определении интервала рыночных цен не учитывается цена, примененная в анализируемой сделке. При наличии достаточного количества сопоставимых сделок, совершенных налогоплательщиком, сторонами которых не являются взаимозависимые лица, при определении интервала рыночных цен не учитывается информация по прочим сделкам;\n\n2) минимальное значение интервала рыночных цен определяется в следующем порядке:\n\nесли частное от деления на четыре числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то минимальным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на четыре числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то минимальным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу;\n\n3) максимальное значение интервала рыночных цен определяется в следующем порядке:\n\nесли произведение 0,75 и числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то максимальным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли произведение 0,75 и числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то максимальным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный сумме целой части этого дробного числа, увеличенной на единицу;\n\n4) медианное значение интервала рыночных цен определяется в следующем порядке:\n\nесли частное от деления на два числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, является целым числом, то медианным значением интервала рыночных цен признается среднее арифметическое значения цены, имеющего в выборке порядковый номер, равный этому целому числу, и значения цены, имеющего следующий по возрастанию порядковый номер в этой выборке;\n\nесли частное от деления на два числа значений цен в выборке, образованной в соответствии с подпунктом 1 настоящего пункта, не является целым числом, то медианным значением интервала рыночных цен признается значение цены, имеющее в выборке порядковый номер, равный целой части этого дробного числа, увеличенной на единицу.\n\n(Дополнение подпунктом - Федеральный закон от 27.11.2023 № 539-ФЗ)\n\n1) обоснованные и подтвержденные документально и (или) источниками информации расходы, необходимые для доставки товаров (работ, услуг) на соответствующий рынок;\n\n2) расходы на уплату вывозных таможенных пошлин;\n\n3) условия платежа;\n\n4) комиссионное (агентское) вознаграждение торгового брокера (комиссионера или агента) за выполнение им торгово-посреднических функций.\n\nВ случае, если цена, примененная в анализируемой сделке, меньше минимального значения интервала рыночных цен, определенного в соответствии с положениями настоящей статьи, или превышает максимальное значение интервала рыночных цен, определенного в соответствии с положениями настоящей статьи, для целей налогообложения принимается цена, которая соответствует медианному значению интервала рыночных цен.\n\nПрименение для целей налогообложения медианного значения интервала рыночных цен в соответствии с настоящим пунктом производится при условии, что это не приводит к уменьшению суммы налога, подлежащего уплате в бюджетную систему Российской Федерации, или увеличению суммы убытка, определяемого в соответствии с главой 25 настоящего Кодекса, если иное не предусмотрено по результатам взаимосогласительной процедуры в соответствии с международным договором Российской Федерации по вопросам налогообложения.\n\n(Пункт в редакции  Федерального закона от 27.11.2023 № 539-ФЗ)","article_title":"Статья 105.9. Метод сопоставимых рыночных цен","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2aa6f2b23470dbd73b192870f25406588175452985404f0d1b065e699c5119ce"},{"code_id":"NK_RF","article_number":"106","version_date":"2000-07-31","article_text":"Налоговым правонарушением признается виновно совершенное противоправное (в нарушение законодательства о налогах и сборах) деяние (действие или бездействие) налогоплательщика, плательщика страховых взносов, налогового агента и иных лиц, за которое настоящим Кодексом установлена ответственность. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)","article_title":"Статья 106. Понятие налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"04d6216d03392201b441d1062ca4747a6c9338548bc9f2b5cb668dea92a05391"},{"code_id":"NK_RF","article_number":"108","version_date":"2000-07-31","article_text":"1. Никто не может быть привлечен к ответственности за совершение налогового правонарушения иначе, как по основаниям и в порядке, которые предусмотрены настоящим Кодексом.\n\nОтветственность за неисполнение обязанности по уплате налога на прибыль организаций, налога на доходы физических лиц с прибыли (дохода), приходящейся на долю участника договора инвестиционного товарищества, несет соответствующий участник такого договора, если иное не установлено настоящим Кодексом.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)","article_title":"Статья 108. Общие условия привлечения к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"2d8aaad0e1e47442eedda63a36c130424f2d8e9ff3c5b263b82e845532a753e5"},{"code_id":"NK_RF","article_number":"109","version_date":"2000-07-31","article_text":"1) отсутствие события налогового правонарушения;\n\n2) отсутствие вины лица в совершении налогового правонарушения;\n\n3) совершение деяния, содержащего признаки налогового правонарушения, физическим лицом, не достигшим к моменту совершения деяния шестнадцатилетнего возраста;\n\n4) истечение сроков давности привлечения к ответственности за совершение налогового правонарушения.\n\nВ случае, указанном в настоящем пункте, основанием для непривлечения лица к ответственности за совершение налогового правонарушения является представление копии такой специальной декларации и копий прилагаемых к ней документов и (или) сведений с отметкой налогового органа о приеме.\n\n(Дополнение пунктом - Федеральный закон от 08.06.2015 № 150-ФЗ)","article_title":"Статья 109. Обстоятельства, исключающие привлечение лица к ответственности за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1aa2389ff2159e1e5316861673276067c22e0c2fdd3ffba619ef33970d8eca6e"},{"code_id":"NK_RF","article_number":"11","version_date":"2000-07-31","article_text":"1. Институты, понятия и термины гражданского, семейного и других отраслей законодательства Российской Федерации, используемые в настоящем Кодексе, применяются в том значении, в каком они используются в этих отраслях законодательства, если иное не предусмотрено настоящим Кодексом.\n\nорганизации - юридические лица, образованные в соответствии с законодательством Российской Федерации, международные компании (далее - российские организации), а также иностранные юридические лица, компании и другие корпоративные образования, обладающие гражданской правоспособностью, созданные в соответствии с законодательством иностранных государств, международные организации, филиалы и представительства указанных иностранных лиц и международных организаций, созданные на территории Российской Федерации (далее - иностранные организации); (В редакции Федерального закона от 03.08.2018 № 294-ФЗ)\n\nфизические лица - граждане Российской Федерации, иностранные граждане и лица без гражданства;\n\nиндивидуальные предприниматели - физические лица, зарегистрированные в установленном порядке и осуществляющие предпринимательскую деятельность без образования юридического лица, главы крестьянских (фермерских) хозяйств. Физические лица, осуществляющие предпринимательскую деятельность без образования юридического лица, но не зарегистрировавшиеся в качестве индивидуальных предпринимателей в нарушение требований гражданского законодательства Российской Федерации, при исполнении обязанностей, возложенных на них настоящим Кодексом, не вправе ссылаться на то, что они не являются индивидуальными предпринимателями; (В редакции федеральных законов от 23.12.2003 № 185-ФЗ; от 27.07.2006 № 137-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nлица (лицо) - организации и (или) физические лица;\n\nиностранная структура без образования юридического лица - организационная форма, созданная в соответствии с законодательством иностранного государства (территории) без образования юридического лица (в частности, фонд, партнерство, товарищество, траст, иная форма осуществления коллективных инвестиций и (или) доверительного управления), которая в соответствии со своим личным законом вправе осуществлять деятельность, направленную на извлечение дохода (прибыли) в интересах своих участников (пайщиков, доверителей или иных лиц) либо иных бенефициаров; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nиностранные финансовые посредники - иностранные фондовые биржи и иностранные депозитарно-клиринговые организации, включенные в перечень, утверждаемый Центральным банком Российской Федерации по согласованию с Министерством финансов Российской Федерации; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nпубличные компании - российские и иностранные организации, являющиеся эмитентами ценных бумаг, которые (либо депозитарные расписки на которые) прошли процедуру листинга и (или) были допущены к обращению на одной или нескольких российских биржах, имеющих соответствующую лицензию, или биржах, включенных в перечень иностранных финансовых посредников; (Дополнение абзацем - Федеральный закон от 24.11.2014 № 376-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nабзац; (Утратил силу - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nбанки (банк) - коммерческие банки и другие кредитные организации, имеющие лицензию Центрального банка Российской Федерации;\n\nсчета (счет) - расчетные (текущие) и иные счета в банках, открытые на основании договора банковского счета, включая счета в банках, открытые на основании договора банковского счета в драгоценных металлах; (В редакции федеральных законов от 28.06.2013 № 134-ФЗ; от 27.11.2017 № 343-ФЗ)\n\nсчет цифрового рубля - счет, открытый оператором платформы цифрового рубля на основании договора счета цифрового рубля; (Дополнение абзацем - Федеральный закон от 19.12.2023 № 610-ФЗ)\n\nлицевые счета - счета, открытые в органах Федерального казначейства (иных органах, осуществляющих открытие и ведение лицевых счетов) в соответствии с бюджетным законодательством Российской Федерации; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nсчет Федерального казначейства - казначейский счет для осуществления и отражения операций по учету и распределению поступлений; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 23.11.2020 № 374-ФЗ)\n\nисточник выплаты доходов налогоплательщику - организация или физическое лицо, от которых налогоплательщик получает доход;\n\nнедоимка - сумма налога, сумма сбора или сумма страховых взносов, не уплаченная (не перечисленная) в установленный законодательством о налогах и сборах срок; (В редакции  федеральных законов от 03.07.2016 № 243-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nсвидетельство о постановке на учет в налоговом органе - документ, подтверждающий постановку на учет российской организации, иностранной организации, физического лица в налоговом органе соответственно по месту нахождения российской организации, месту нахождения международной организации, по месту осуществления иностранной организацией деятельности на территории Российской Федерации через свое обособленное подразделение, по месту жительства физического лица; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nуведомление о постановке на учет в налоговом органе - документ, подтверждающий постановку на учет в налоговом органе организации или физического лица, в том числе индивидуального предпринимателя, по основаниям, установленным настоящим Кодексом, за исключением оснований, по которым настоящим Кодексом предусмотрена выдача свидетельства о постановке на учет в налоговом органе; (Дополнение абзацем - Федеральный закон от 23.12.2003 № 185-ФЗ) (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nсезонное производство - производство, осуществление которого непосредственно связано с природными, климатическими условиями и со временем года. Данное понятие применяется в отношении организации и индивидуального предпринимателя, если в определенные налоговые периоды (квартал, полугодие) их производственная деятельность не осуществляется в силу природных и климатических условий;\n\nабзац; (Утратил силу - Федеральный закон от 23.12.2003 № 185-ФЗ)\n\nместо нахождения обособленного подразделения российской организации - место осуществления этой организацией деятельности через свое обособленное подразделение; (В редакции Федерального закона от 27.07.2010 № 229-ФЗ)\n\nместо жительства физического лица - адрес (наименование субъекта Российской Федерации, района, города, иного населенного пункта, улицы, номера дома, квартиры), по которому физическое лицо зарегистрировано по месту жительства в порядке, установленном законодательством Российской Федерации. При отсутствии у физического лица места жительства на территории Российской Федерации для целей настоящего Кодекса место жительства может определяться по просьбе этого физического лица по месту его пребывания. При этом местом пребывания физического лица признается место, где физическое лицо проживает временно по адресу (наименование субъекта Российской Федерации, района, города, иного населенного пункта, улицы, номер дома, квартиры), по которому физическое лицо зарегистрировано по месту пребывания в порядке, установленном законодательством Российской Федерации; (В редакции федеральных законов от 23.12.2003 № 185-ФЗ; от 27.07.2010 № 229-ФЗ)\n\nобособленное подразделение организации - любое территориально обособленное от нее подразделение, по месту нахождения которого оборудованы стационарные рабочие места. Признание обособленного подразделения организации таковым производится независимо от того, отражено или не отражено его создание в учредительных или иных организационно-распорядительных документах организации, и от полномочий, которыми наделяется указанное подразделение. При этом рабочее место считается стационарным, если оно создается на срок более одного месяца;\n\nучетная политика для целей налогообложения - выбранная налогоплательщиком совокупность допускаемых настоящим Кодексом способов (методов) определения доходов и (или) расходов, их признания, оценки и распределения, а также учета иных необходимых для целей налогообложения показателей финансово-хозяйственной деятельности налогоплательщика; (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\nтерритория Российской Федерации и иные территории, находящиеся под ее юрисдикцией, - территория Российской Федерации, а также территории искусственных островов, установок и сооружений, над которыми Российская Федерация осуществляет юрисдикцию в соответствии с законодательством Российской Федерации и нормами международного права; (Дополнение абзацем - Федеральный закон от 27.11.2010 № 306-ФЗ)\n\nкоэффициент-дефлятор - коэффициент, устанавливаемый ежегодно на каждый следующий календарный год и рассчитываемый как произведение коэффициента-дефлятора, применяемого для целей соответствующих глав настоящего Кодекса в предшествующем календарном году, и коэффициента, учитывающего изменение потребительских цен на товары (работы, услуги) в Российской Федерации в предшествующем календарном году. Коэффициенты-дефляторы устанавливаются, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах, федеральным органом исполнительной власти, осуществляющим функции по нормативно-правовому регулированию в сфере анализа и прогнозирования социально-экономического развития, в соответствии с данными государственной статистической отчетности и, если иное не предусмотрено законодательством Российской Федерации о налогах и сборах, подлежат официальному опубликованию не позднее 20 ноября года, в котором устанавливаются коэффициенты-дефляторы; (Дополнение абзацем - Федеральный закон от 25.06.2012 № 94-ФЗ) (В редакции федеральных законов  от 29.12.2015 № 386-ФЗ;  от 27.11.2017 № 335-ФЗ)\n\nсовокупная обязанность - общая сумма налогов, авансовых платежей, сборов, страховых взносов, пеней, штрафов, процентов, которую обязан уплатить (перечислить) налогоплательщик, плательщик сбора, плательщик страховых взносов и (или) налоговый агент, и сумма налога, подлежащая возврату в бюджетную систему Российской Федерации в случаях, предусмотренных настоящим Кодексом. При этом в совокупную обязанность не включаются суммы налога на доходы физических лиц, уплачиваемого в порядке, установленном статьей 2271 настоящего Кодекса, и суммы государственной пошлины, за исключением государственной пошлины, в отношении уплаты которой арбитражным судом выдан исполнительный документ; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nзадолженность по уплате налогов, сборов и страховых взносов в бюджеты бюджетной системы Российской Федерации (далее - задолженность) - общая сумма недоимок, а также не уплаченных налогоплательщиком, плательщиком сборов, плательщиком страховых взносов и (или) налоговым агентом пеней, штрафов и процентов, предусмотренных настоящим Кодексом, и сумм налогов, подлежащих возврату в бюджетную систему Российской Федерации в случаях, предусмотренных настоящим Кодексом, равная размеру отрицательного сальдо единого налогового счета этого лица, а также сумм, не учитываемых в совокупной обязанности в соответствии с подпунктами 10 и 101 пункта 5, подпунктами 2 - 34, 5 и 6 пункта 7 статьи 113 настоящего Кодекса; (Дополнение абзацем - Федеральный закон от 14.07.2022 № 263-ФЗ) (В редакции  Федерального закона от 31.07.2025 № 287-ФЗ)\n\n\"Инвестиционный проект\" - ограниченный по времени и затрачиваемым ресурсам комплекс мероприятий, предусматривающих создание и последующую эксплуатацию нового имущественного комплекса и (или) нематериальных активов либо модернизацию (реконструкцию, техническое перевооружение) существующего имущественного комплекса в целях создания нового производства товаров (работ, услуг), увеличения объемов существующего производства товаров (работ, услуг) и (или) предотвращения (минимизации) негативного влияния на окружающую среду. (Дополнение абзацем - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\n(Пункт в редакции Федерального закона от 09.07.1999 № 154-ФЗ)","article_title":"Статья 11. Институты, понятия и термины, используемые в настоящем Кодексе","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4599df59cd5566bef8cc34744172fa2d570096a1a7d9b66ca03ee14124da99b1"},{"code_id":"NK_RF","article_number":"110","version_date":"2000-07-31","article_text":"1. Виновным в совершении налогового правонарушения признается лицо, совершившее противоправное деяние умышленно или по неосторожности.\n\n2. Налоговое правонарушение признается совершенным умышленно, если лицо, его совершившее, осознавало противоправный характер своих действий (бездействия), желало либо сознательно допускало наступление вредных последствий таких действий (бездействия).\n\n3. Налоговое правонарушение признается совершенным по неосторожности, если лицо, его совершившее, не осознавало противоправного характера своих действий (бездействия) либо вредного характера последствий, возникших вследствие этих действий (бездействия), хотя должно было и могло это осознавать.\n\n4. Вина организации в совершении налогового правонарушения определяется в зависимости от вины ее должностных лиц, либо ее представителей, действия (бездействие) которых обусловили совершение данного налогового правонарушения.","article_title":"Статья 110. Формы вины при совершении налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"71dede02a4d7e55719c3e660125af9aa22c1293d623a29a440ef6444a804a115"},{"code_id":"NK_RF","article_number":"111","version_date":"2000-07-31","article_text":"1. Обстоятельствами, исключающими вину лица в совершении налогового правонарушения, признаются:\n\n1) совершение деяния, содержащего признаки налогового правонарушения, вследствие стихийного бедствия или других чрезвычайных и непреодолимых обстоятельств (указанные обстоятельства устанавливаются наличием общеизвестных фактов, публикаций в средствах массовой информации и иными способами, не нуждающимися в специальных средствах доказывания); (В редакции Федерального закона от 09.07.1999 № 154-ФЗ)\n\n2) совершение деяния, содержащего признаки налогового правонарушения, физическим лицом, находившимся в момент его совершения в состоянии, при котором это лицо не могло отдавать себе отчета в своих действиях или руководить ими вследствие болезненного состояния (указанные обстоятельства доказываются предоставлением в налоговый орган документов, которые по смыслу, содержанию и дате относятся к тому налоговому (расчетному) периоду, в котором совершено налоговое правонарушение); (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n3) выполнение налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) письменных разъяснений о порядке исчисления, уплаты налога (сбора, страховых взносов) или по иным вопросам применения законодательства о налогах и сборах, данных ему либо неопределенному кругу лиц финансовым, налоговым или другим уполномоченным органом государственной власти (уполномоченным должностным лицом этого органа) в пределах его компетенции (указанные обстоятельства устанавливаются при наличии соответствующего документа этого органа, по смыслу и содержанию относящегося к налоговым (расчетным) периодам, в которых совершено налоговое правонарушение, независимо от даты издания такого документа), и (или) выполнение налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) мотивированного мнения налогового органа, направленного ему в ходе проведения налогового мониторинга. (В редакции федеральных законов от 04.11.2014 № 348-ФЗ; от 03.07.2016 № 243-ФЗ)\n\nПоложение настоящего подпункта не применяется в случае, если указанные письменные разъяснения, мотивированное мнение налогового органа основаны на неполной или недостоверной информации, представленной налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом); (В редакции федеральных законов от 04.11.2014 № 348-ФЗ; от 03.07.2016 № 243-ФЗ)\n\n(Подпункт в редакции Федерального закона от 27.07.2006 № 137-ФЗ)\n\n4) иные обстоятельства, которые могут быть признаны судом или налоговым органом, рассматривающим дело, исключающими вину лица в совершении налогового правонарушения. (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n2. При наличии обстоятельств, указанных в пункте 1 настоящей статьи, лицо не подлежит ответственности за совершение налогового правонарушения.","article_title":"Статья 111. Обстоятельства, исключающие вину лица в совершении налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"697e36d7869ed33b8f29e3bcf66847d4d71e7297af6d840a1ea269f99c140532"},{"code_id":"NK_RF","article_number":"112","version_date":"2000-07-31","article_text":"1. Обстоятельствами, смягчающими ответственность за совершение налогового правонарушения, признаются:\n\n1) совершение правонарушения вследствие стечения тяжелых личных или семейных обстоятельств;\n\n2) совершение правонарушения под влиянием угрозы или принуждения либо в силу материальной, служебной или иной зависимости;\n\n21) тяжелое материальное положение физического лица, привлекаемого к ответственности за совершение налогового правонарушения; (Дополнение подпунктом - Федеральный закон от 27.07.2006 № 137-ФЗ)\n\n3) иные обстоятельства, которые судом или налоговым органом, рассматривающим дело, могут быть признаны смягчающими ответственность. (В редакции федеральных законов от 09.07.1999 № 154-ФЗ; от 04.11.2005 № 137-ФЗ)\n\n2. Обстоятельством, отягчающим ответственность, признается совершение налогового правонарушения лицом, ранее привлекаемым к ответственности за аналогичное правонарушение.","article_title":"Статья 112. Обстоятельства, смягчающие и отягчающие ответственность за совершение налогового правонарушения","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddb6089da47eac7a9c70d28dbb64aeed7e62777babe0f580cb5bcd1b7d2a2c59"}]$law7d0052$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
